import{_ as a,o as t,c as n,a0 as s}from"./chunks/framework.akKRIpjQ.js";const u=JSON.parse('{"title":"06 · Settings · Privacy · Feedback · FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-settings-faq.md","filePath":"guide/06-settings-faq.md"}'),o={name:"guide/06-settings-faq.md"};function i(r,e,l,p,d,c){return t(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="_06-·-settings-·-privacy-·-feedback-·-faq" tabindex="-1">06 · Settings · Privacy · Feedback · FAQ <a class="header-anchor" href="#_06-·-settings-·-privacy-·-feedback-·-faq" aria-label="Permalink to &quot;06 · Settings · Privacy · Feedback · FAQ&quot;">​</a></h1><blockquote><p>The <code>Me</code> tab dissected, plus the FAQ roundup.</p></blockquote><h2 id="the-full-me-tab" tabindex="-1">The full <code>Me</code> tab <a class="header-anchor" href="#the-full-me-tab" aria-label="Permalink to &quot;The full \`Me\` tab&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────┐</span></span>
<span class="line"><span>│ Me                               │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ Appearance                       │</span></span>
<span class="line"><span>│  · Theme (Follow / Light / Dark / OLED black) │</span></span>
<span class="line"><span>│  · Units (mm/in, g/oz, lbs/kg)    │</span></span>
<span class="line"><span>│  · Font size (Standard / Large)   │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ Data                             │</span></span>
<span class="line"><span>│  · Export (JSON / CSV)           │</span></span>
<span class="line"><span>│  · Import                        │</span></span>
<span class="line"><span>│  · Delete all data               │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ Notifications                    │</span></span>
<span class="line"><span>│  · Restring reminders            │</span></span>
<span class="line"><span>│  · Reminder time window (09:00 / 12:00 / etc.) │</span></span>
<span class="line"><span>│  · Keep original photos (V1.1)   │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ Privacy &amp; licenses               │</span></span>
<span class="line"><span>│  · Privacy manifest              │</span></span>
<span class="line"><span>│  · Open-source licenses (MediaPipe, Fonts) │</span></span>
<span class="line"><span>│  · Third-party components        │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ Feedback                         │</span></span>
<span class="line"><span>│  · Send feedback                 │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│ About                            │</span></span>
<span class="line"><span>│  · Version (V1.0.x build xxx)   │</span></span>
<span class="line"><span>│  · App store link                │</span></span>
<span class="line"><span>└───────────────────────────────────┘</span></span></code></pre></div><h2 id="theme-display" tabindex="-1">Theme &amp; display <a class="header-anchor" href="#theme-display" aria-label="Permalink to &quot;Theme &amp; display&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Options</th><th>Default</th></tr></thead><tbody><tr><td>Theme</td><td>Follow system / Light / Dark / OLED pure black (V1.1+)</td><td>Follow system</td></tr><tr><td>Units</td><td>Metric / Imperial / Both side-by-side</td><td>Metric</td></tr><tr><td>Font size</td><td>Standard / Large / Huge</td><td>Standard</td></tr></tbody></table><blockquote><p>OLED pure black makes backgrounds <code>#000000</code>, saving battery and giving a cleaner dark mode.</p></blockquote><h2 id="data-management" tabindex="-1">Data management <a class="header-anchor" href="#data-management" aria-label="Permalink to &quot;Data management&quot;">​</a></h2><h3 id="export-json" tabindex="-1">Export JSON <a class="header-anchor" href="#export-json" aria-label="Permalink to &quot;Export JSON&quot;">​</a></h3><p><code>Me → Data → Export</code> → pick the scope (racket profile / stringing log / grip history / all) → generates a <code>.json</code> file → system share sheet.</p><blockquote><p>The file is <strong>not encrypted</strong> — it&#39;s your private data. Email it to yourself, AirDrop to your own computer, or save it to an encrypted cloud drive. <strong>Don&#39;t share it on social media</strong>.</p></blockquote><h3 id="import-json" tabindex="-1">Import JSON <a class="header-anchor" href="#import-json" aria-label="Permalink to &quot;Import JSON&quot;">​</a></h3><p><code>Me → Data → Import</code> → pick a JSON. Duplicate entries (matched by ID) are skipped; existing data is not overwritten.</p><h3 id="delete-all-data" tabindex="-1">Delete all data <a class="header-anchor" href="#delete-all-data" aria-label="Permalink to &quot;Delete all data&quot;">​</a></h3><p><code>Me → Data → Delete all data</code>. Requires double confirmation.</p><blockquote><p>Once deleted it&#39;s gone (your previous export is your only copy).</p></blockquote><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Restring reminder</td><td>On</td><td>Needs system-level notification permission</td></tr><tr><td>Reminder time window</td><td>09:00</td><td>09:00 / 12:00 / 20:00</td></tr><tr><td>Advance reminder</td><td>3 days before</td><td>At 3 / 1 / 0 days, each fires once</td></tr></tbody></table><p>If notifications are off, open system <code>Settings → Apps → AceCrush Craft → Notifications</code> and re-enable, then re-toggle in the App.</p><h2 id="privacy-licenses" tabindex="-1">Privacy &amp; licenses <a class="header-anchor" href="#privacy-licenses" aria-label="Permalink to &quot;Privacy &amp; licenses&quot;">​</a></h2><h3 id="privacy-permissions" tabindex="-1">Privacy &amp; permissions <a class="header-anchor" href="#privacy-permissions" aria-label="Permalink to &quot;Privacy &amp; permissions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>When requested</th><th>Used for</th><th>Can you decline?</th></tr></thead><tbody><tr><td><strong>Notifications</strong></td><td>First launch</td><td>Restring reminder</td><td>Yes (turn off → no reminder)</td></tr><tr><td><strong>Camera</strong></td><td>V1.1 photo measurement</td><td>Palm photo</td><td>Yes (use manual adjust instead)</td></tr><tr><td><strong>Photos / Files</strong></td><td>User-initiated &quot;save to gallery&quot;</td><td>Export video / image</td><td>Yes (use &quot;share to&quot; flow instead)</td></tr><tr><td><strong>Network</strong></td><td>First time needed</td><td>Feedback submission</td><td>Off → feedback delays until you go online</td></tr></tbody></table><blockquote><p>This list reflects the complete set V1.0+ requests. The &quot;Network&quot; permission is only used <strong>when you submit feedback</strong>; <strong>never used by default</strong>.</p><p>Location / contacts / phone ID / IMEI / advertising ID — <strong>never requested</strong>.</p></blockquote><h3 id="open-source-licenses" tabindex="-1">Open-source licenses <a class="header-anchor" href="#open-source-licenses" aria-label="Permalink to &quot;Open-source licenses&quot;">​</a></h3><p>The bundled <a href="https://github.com/google-ai-edge/mediapipe" target="_blank" rel="noreferrer">MediaPipe</a> and its Pose / Hand models are licensed under Apache License 2.0. The full text is bundled in <code>Me → Open-source licenses</code> as Assets, available offline.</p><p>The App uses default system fonts (Roboto / SF Pro / PingFang); no third-party fonts are bundled.</p><h3 id="third-party-components" tabindex="-1">Third-party components <a class="header-anchor" href="#third-party-components" aria-label="Permalink to &quot;Third-party components&quot;">​</a></h3><p>Only open-source dependencies (MediaPipe + a couple of Dart packages). Full list: <code>Me → Third-party components</code>.</p><hr><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><p><code>Me → Send feedback</code>. Categories (Bug / Suggestion / Other) + text (up to 2000 chars).</p><p>Each record <strong>includes</strong>:</p><ul><li>App version (e.g. V1.0.2 build 2026-08-30)</li><li>OS version (Android 14 / API 34)</li><li>Device model (e.g. Xiaomi 14)</li><li>Screen resolution / DPI</li><li>Submission timestamp</li></ul><p><strong>Does not include</strong> your account (there is none), geolocation, photos, grip history, or any private data.</p><p>After submission → backend ticket → team replies in their queue. To follow up, go to <code>Me → Feedback history</code>.</p><hr><h2 id="common-questions-faq" tabindex="-1">Common questions (FAQ) <a class="header-anchor" href="#common-questions-faq" aria-label="Permalink to &quot;Common questions (FAQ)&quot;">​</a></h2><h3 id="_1-is-the-app-completely-free" tabindex="-1">1. Is the App completely free? <a class="header-anchor" href="#_1-is-the-app-completely-free" aria-label="Permalink to &quot;1. Is the App completely free?&quot;">​</a></h3><p><strong>Yes</strong>. No ads, no IAP, no premium tier.</p><h3 id="_2-will-v1-1-cost-money" tabindex="-1">2. Will V1.1 cost money? <a class="header-anchor" href="#_2-will-v1-1-cost-money" aria-label="Permalink to &quot;2. Will V1.1 cost money?&quot;">​</a></h3><p><strong>No</strong>.</p><h3 id="_3-is-my-data-uploaded" tabindex="-1">3. Is my data uploaded? <a class="header-anchor" href="#_3-is-my-data-uploaded" aria-label="Permalink to &quot;3. Is my data uploaded?&quot;">​</a></h3><p><strong>No</strong>, unless you tap <a href="#feedback">Feedback</a>.</p><h3 id="_4-after-uninstall-can-i-recover-data" tabindex="-1">4. After uninstall, can I recover data? <a class="header-anchor" href="#_4-after-uninstall-can-i-recover-data" aria-label="Permalink to &quot;4. After uninstall, can I recover data?&quot;">​</a></h3><p>No — there&#39;s no cloud backup. See <a href="./04-stringing-log.html#deleting-a-racket">04 · Data migration</a>.</p><h3 id="_5-when-is-ios-coming" tabindex="-1">5. When is iOS coming? <a class="header-anchor" href="#_5-when-is-ios-coming" aria-label="Permalink to &quot;5. When is iOS coming?&quot;">​</a></h3><p>No available build yet. See <a href="./00-introduction.html#supported-platforms">00 · Supported platforms</a>.</p><h3 id="_6-app-launches-blank-hangs-—-what-now" tabindex="-1">6. App launches blank / hangs — what now? <a class="header-anchor" href="#_6-app-launches-blank-hangs-—-what-now" aria-label="Permalink to &quot;6. App launches blank / hangs — what now?&quot;">​</a></h3><ol><li>Relaunch</li><li>Still broken? <code>Me → Data → Delete all data</code> (export JSON first)</li><li>Still broken? Uninstall + reinstall</li></ol><h3 id="_7-how-do-i-put-the-icon-on-the-home-screen" tabindex="-1">7. How do I put the icon on the home screen? <a class="header-anchor" href="#_7-how-do-i-put-the-icon-on-the-home-screen" aria-label="Permalink to &quot;7. How do I put the icon on the home screen?&quot;">​</a></h3><p>Android places the icon at install. Long-press to drop into a folder if you&#39;d like.</p><h3 id="_8-i-use-a-third-party-launcher-e-g-nova-and-the-icon-looks-different" tabindex="-1">8. I use a third-party launcher (e.g. Nova) and the icon looks different? <a class="header-anchor" href="#_8-i-use-a-third-party-launcher-e-g-nova-and-the-icon-looks-different" aria-label="Permalink to &quot;8. I use a third-party launcher (e.g. Nova) and the icon looks different?&quot;">​</a></h3><p>Adaptive icons render differently across launchers; behavior is unaffected.</p><h3 id="_9-can-i-export-as-pdf-excel" tabindex="-1">9. Can I export as PDF / Excel? <a class="header-anchor" href="#_9-can-i-export-as-pdf-excel" aria-label="Permalink to &quot;9. Can I export as PDF / Excel?&quot;">​</a></h3><p>V1.0 is JSON only. V1.1+ adds CSV (opens in Excel).</p><h3 id="_10-can-i-contribute-a-translation" tabindex="-1">10. Can I contribute a translation? <a class="header-anchor" href="#_10-can-i-contribute-a-translation" aria-label="Permalink to &quot;10. Can I contribute a translation?&quot;">​</a></h3><p>Not open yet. V1.0 ships in 简体中文 + English.</p><h3 id="_11-will-this-project-go-open-source" tabindex="-1">11. Will this project go open-source? <a class="header-anchor" href="#_11-will-this-project-go-open-source" aria-label="Permalink to &quot;11. Will this project go open-source?&quot;">​</a></h3><p><a href="./00-introduction.html#what-v10-is-not-doing">A decision will be made after the V1.0 store launch</a>. Source code and build scripts are not currently provided.</p><h3 id="_12-i-hit-a-bug-in-testing-—-how-to-report" tabindex="-1">12. I hit a Bug in testing — how to report? <a class="header-anchor" href="#_12-i-hit-a-bug-in-testing-—-how-to-report" aria-label="Permalink to &quot;12. I hit a Bug in testing — how to report?&quot;">​</a></h3><p><strong>Fastest</strong>: in-App <code>Me → Send feedback</code>. <strong>Email</strong>: <a href="mailto:support@acecrush.dev" target="_blank" rel="noreferrer">support@acecrush.dev</a> (attach screenshots).</p><h3 id="_13-will-ios-safari-deep-link-to-the-app-work" tabindex="-1">13. Will iOS Safari deep-link to the App work? <a class="header-anchor" href="#_13-will-ios-safari-deep-link-to-the-app-work" aria-label="Permalink to &quot;13. Will iOS Safari deep-link to the App work?&quot;">​</a></h3><p><strong>It won&#39;t</strong>, because there&#39;s no iOS build and Universal Links aren&#39;t configured. Open the official site instead.</p><hr><h2 id="bug-report-template" tabindex="-1">Bug report template <a class="header-anchor" href="#bug-report-template" aria-label="Permalink to &quot;Bug report template&quot;">​</a></h2><p>If you email, copy this template — it speeds up triage:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App version: V1.0.x build xxx</span></span>
<span class="line"><span>Device: &lt;model + Android version&gt;</span></span>
<span class="line"><span>Steps to reproduce:</span></span>
<span class="line"><span>  1. ...</span></span>
<span class="line"><span>  2. ...</span></span>
<span class="line"><span>Expected behaviour:</span></span>
<span class="line"><span>Actual behaviour:</span></span>
<span class="line"><span>Screenshot: &lt;attach&gt;</span></span>
<span class="line"><span>Log: &lt;pull from /Android/data/com.acecrushcraft.app/files/logs/*.log&gt;</span></span></code></pre></div><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li>Email: <a href="mailto:support@acecrush.dev" target="_blank" rel="noreferrer">support@acecrush.dev</a></li><li>Xiaohongshu: <code>@AceCrush</code></li></ul><blockquote><p>Email is usually answered within 1–3 working days. XHS comments are <strong>not</strong> a feedback channel.</p></blockquote>`,70)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
